def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    last_gap = {}

    # Horizontal rows encode vertical beams at their missing cells. Each
    # beam runs upward until the preceding beam at that column.
    for r, row in enumerate(grid):
        for color in set(row) - {0}:
            cols = [c for c, value in enumerate(row) if value == color]
            if len(cols) < 2:
                continue
            for c in range(min(cols), max(cols) + 1):
                if row[c] == 0:
                    start = last_gap.get(c, -1) + 1
                    for rr in range(start, r + 1):
                        if out[rr][c] == 0:
                            out[rr][c] = color
                    last_gap[c] = r

    # Bottom vertical beams extend upward to the nearest horizontal beam.
    for c in range(w):
        r = h - 1
        while r >= 0:
            color = grid[r][c]
            if color == 0:
                r -= 1
                continue
            top = r
            while top > 0 and grid[top - 1][c] == color:
                top -= 1
            if r - top + 1 >= 2:
                rr = top - 1
                while rr >= 0 and out[rr][c] == 0:
                    out[rr][c] = color
                    rr -= 1
            r = top - 1
    return out
