def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [[] for _ in range(w)]

    # Internal one-cell gaps in horizontal bars are channel markers.
    for r, row in enumerate(grid):
        for c in range(1, w - 1):
            if row[c] == 0 and row[c - 1] != 0 and row[c - 1] == row[c + 1]:
                color = row[c - 1]
                markers[c].append((r, color))

    # Bottom-edge vertical marker: use the top of its contiguous stem run.
    for c, color in enumerate(grid[-1]):
        if color:
            top = h - 1
            while top > 0 and grid[top - 1][c] == color:
                top -= 1
            markers[c].append((top, color))

    # Each marker colors its vertical band up to the previous marker.
    for c in range(w):
        marks = sorted(markers[c])
        previous = -1
        for r, color in marks:
            for rr in range(previous + 1, r + 1):
                out[rr][c] = color
            previous = r
        # If the last marker is not on the bottom edge, leave below it unchanged.
    return out

